ALTER TABLE public.treatments ADD COLUMN start_screen jsonb;
ALTER TABLE public.booking_links ADD COLUMN start_screen_mode text NOT NULL DEFAULT 'treatment' CHECK(start_screen_mode IN ('treatment','custom','none')), ADD COLUMN start_screen jsonb;
CREATE FUNCTION public.validate_start_screen() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE s jsonb; BEGIN s=NEW.start_screen; IF s IS NULL THEN RETURN NEW; END IF; IF jsonb_typeof(s)<>'object' OR char_length(coalesce(s->>'body',''))>300 OR char_length(coalesce(s->>'body_en',''))>300 THEN RAISE EXCEPTION 'Startschermtekst mag maximaal 300 tekens bevatten'; END IF; IF coalesce(s->>'form','none') NOT IN ('none','list','steps','testimonial','practitioner') THEN RAISE EXCEPTION 'Onbekende startschermvorm'; END IF; IF jsonb_array_length(coalesce(s->'bullets','[]'))>4 OR jsonb_array_length(coalesce(s->'step_items','[]'))>4 OR jsonb_array_length(coalesce(s->'bullets_en','[]'))>4 OR jsonb_array_length(coalesce(s->'step_items_en','[]'))>4 THEN RAISE EXCEPTION 'Maximaal vier punten of stappen'; END IF; RETURN NEW; END $$;
CREATE TRIGGER treatment_start_screen BEFORE INSERT OR UPDATE ON public.treatments FOR EACH ROW EXECUTE FUNCTION public.validate_start_screen();
CREATE TRIGGER link_start_screen BEFORE INSERT OR UPDATE ON public.booking_links FOR EACH ROW EXECUTE FUNCTION public.validate_start_screen();